// Group open issues by assignee; count by status.
const issues = $input.all().map(i => i.json);
const byAssignee = {}; const byStatus = {};
for (const it of issues) {
  const f = it.fields || {};
  const who = f.assignee?.displayName || 'Unassigned';
  const st = f.status?.name || 'Unknown';
  (byAssignee[who] = byAssignee[who] || []).push(it.key + ' ' + (f.summary||''));
  byStatus[st] = (byStatus[st] || 0) + 1;
}
const lines = Object.entries(byAssignee).map(([who, items]) => '**' + who + '** (' + items.length + '): ' + items.slice(0,8).join(', '));
const statusLine = Object.entries(byStatus).map(([s,n]) => s + ': ' + n).join(' · ');
return [{ json: { total: issues.length, statusLine, lines } }];
